// Teruskan pembacaan ke MaintHub dengan API key yang disimpan di Node-RED (bukan di ESP32).
const base = (env.get('MAINTHUB_URL') || '').replace(/\/+$/, '');
const key = env.get('MAINTHUB_KEY');
if (!base || !key) { node.error('Isi MAINTHUB_URL dan MAINTHUB_KEY di tab flow ini'); msg.statusCode = 500; msg.payload = { error: 'gateway belum dikonfigurasi' }; return [null, msg]; }
const b = msg.payload;
const readings = Array.isArray(b) ? b : (b && b.readings);
if (!Array.isArray(readings) || !readings.length || readings.length > 500) { msg.statusCode = 400; msg.payload = { error: 'readings kosong atau > 500' }; return [null, msg]; }
msg.url = base + '/api/ingest/readings';
msg.method = 'POST';
msg.headers = { 'x-api-key': key, 'content-type': 'application/json' };
msg.payload = { readings };
return [msg, null];

// Teruskan balasan MaintHub apa adanya ke ESP32 (200 = terima; 401/400 dst diteruskan agar firmware tahu).
msg.statusCode = msg.statusCode || 502;
if (msg.statusCode >= 400) node.warn('MaintHub membalas ' + msg.statusCode + ': ' + JSON.stringify(msg.payload).slice(0, 200));
else if (msg.payload && msg.payload.errors && msg.payload.errors.length) node.warn('Sebagian ditolak: ' + JSON.stringify(msg.payload.errors).slice(0, 300));
return msg;

// Topik: mainthub/<KODE-ASET>/telemetry   Isi JSON: {"oil_temp":71.2,"motor_current":17.8,"running_hours":1204.5,"ts":1794800000}
// Setiap kunci selain "ts" dan "plant" menjadi satu tag. Nama kunci harus sama dengan tag di menu Telemetri Mesin.
const parts = (msg.topic || '').split('/');
const asset = parts[1];
let d = msg.payload; if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { node.warn('JSON tidak valid'); return null; } }
if (!asset || !d || typeof d !== 'object') return null;
const readings = [];
for (const [k, v] of Object.entries(d)) {
  if (k === 'ts' || k === 'plant' || typeof v !== 'number' || !isFinite(v)) continue;
  const r = { asset, tag: k.toLowerCase(), value: v };
  if (d.ts) r.ts = d.ts; if (d.plant) r.plant = d.plant;
  readings.push(r);
}
if (!readings.length) return null;
msg.payload = { readings };
return msg;

// Teruskan pembacaan ke MaintHub dengan API key yang disimpan di Node-RED (bukan di ESP32).
const base = (env.get('MAINTHUB_URL') || '').replace(/\/+$/, '');
const key = env.get('MAINTHUB_KEY');
if (!base || !key) { node.error('Isi MAINTHUB_URL dan MAINTHUB_KEY di tab flow ini'); msg.statusCode = 500; msg.payload = { error: 'gateway belum dikonfigurasi' }; return [null, msg]; }
const b = msg.payload;
const readings = Array.isArray(b) ? b : (b && b.readings);
if (!Array.isArray(readings) || !readings.length || readings.length > 500) { msg.statusCode = 400; msg.payload = { error: 'readings kosong atau > 500' }; return [null, msg]; }
msg.url = base + '/api/ingest/readings';
msg.method = 'POST';
msg.headers = { 'x-api-key': key, 'content-type': 'application/json' };
msg.payload = { readings };
return [msg, null];

msg.url = (env.get('MAINTHUB_URL')||'').replace(/\/+$/,'') + '/api/ingest/ping';
msg.method = 'GET';
msg.headers = { 'x-api-key': env.get('MAINTHUB_KEY') };
return msg;

const ok = msg.statusCode === 200 && msg.payload && msg.payload.ok;
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'MaintHub OK (' + msg.payload.key + ')' : 'GAGAL ' + msg.statusCode });
if (!ok) node.warn('Ping MaintHub gagal: ' + msg.statusCode + ' ' + JSON.stringify(msg.payload).slice(0,200));
return null;
